import React from "react"
import { graphql } from "gatsby"
import styled from "styled-components"

import Layout from "components/Layout"
import SEO from "components/SEO"
import VerticalSpace from "components/VerticalSpace"

const SeriesPageWrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 60vh;
  text-align: center;
  padding: 0 16px;
`

const Title = styled.h1`
  font-size: 48px;
  font-weight: 800;
  color: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#0a0a0a'};
  margin-bottom: 16px;
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  
  @media (max-width: 768px) {
    font-size: 36px;
  }
`

const Description = styled.p`
  font-size: 18px;
  color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
  margin: 0;
  max-width: 500px;
  line-height: 1.6;
  
  @media (max-width: 768px) {
    font-size: 16px;
  }
`

const SeriesPage = ({ data }) => {
  const posts = data.allMarkdownRemark.nodes
  
  // 시리즈가 있는 포스트들만 필터링
  const seriesPosts = posts.filter(post => post.frontmatter.series)
  
  return (
    <Layout>
      <SEO title="Series" />
      <VerticalSpace size={48} />
      <SeriesPageWrapper>
        <Title>시리즈</Title>
        <Description>
          {seriesPosts.length === 0 
            ? "아직 시리즈로 구성된 포스트가 없습니다." 
            : `${seriesPosts.length}개의 시리즈가 있습니다.`
          }
        </Description>
      </SeriesPageWrapper>
    </Layout>
  )
}

export default SeriesPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/contents/posts/" } }
    ) {
      nodes {
        frontmatter {
          series
        }
      }
    }
  }
`
